const alternate={0:[1,'日初，向有約定的人問候'],1:[2,'從自在分享的小事開始'],2:[6,'避開水邊難走的近路'],3:[0,'取較穩的路逐段完成'],4:[2,'留一段安靜的時間好好說話'],5:[6,'雨停後再確認地面狀況'],6:[1,'先向熟人確認合適的時間'],7:[3,'回到基本，循線索逐步理解'],8:[5,'放慢一些，記得喝水休息'],9:[4,'記清手上已有的資源'],10:[6,'衣物備妥，優先選熟悉路線'],11:[7,'沿走過的路從近處回找']};

export const OMikuji=packets.flatMap((packet,motif)=>packet.split('\n').map((line,i)=>{
 const [gradeText,poem,meaning]=line.split('|'),grade=Number(gradeText),number=motif*9+i+1;
 const details=fields.map(row=>row[grade]),[edited,advice]=alternate[motif];
 if(grade>=2)details[edited]=advice;
 return{number,grade:FORTUNE_GRADES[grade],motif:FORTUNE_MOTIFS[motif],poem:poem.split('/'),meaning,details};
}));

function randomBelow(limit){
 const max=2**32-2**32%limit,sample=new Uint32Array(1);
 do{crypto.getRandomValues(sample);}while(sample[0]>=max);
 return sample[0]%limit;
}

// Keep the entire draw cycle on the save. At the next cycle boundary, the
// last draw remains in the deck but cannot be selected immediately again.
export function pickFortune(previous,total=OMikuji.length){
 const valid=previous&&typeof previous==='object'?previous:{};
 let cycle=Math.max(1,Number.isSafeInteger(valid.cycle)?valid.cycle:1);
 let used=[...new Set((Array.isArray(valid.used)?valid.used:[]).filter(n=>Number.isInteger(n)&&n>=1&&n<=total))];
 if(used.length===total){cycle++;used=[];}
 const remaining=Array.from({length:total},(_,i)=>i+1).filter(n=>!used.includes(n));
 const choices=remaining.length===1?remaining:remaining.filter(n=>n!==valid.last);
 const number=choices[randomBelow(choices.length)];
 return{number,cycle,deck:{cycle,used:[...used,number],last:number}};
}
